From 556d042565607b4312dcdc495b9c1b762bb8caad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:21:28 +0100
Subject: [PATCH] containmentitem: open the Menu key context menu near the
 focused item

Pressing the Menu key built a fake mouse event with no global position,
so the desktop or applet context menu always opened at the top left
corner of the screen. Use the centre of the focused item, mapped to it.

BUG: 477114
---
 src/plasmaquick/plasmoid/containmentitem.cpp | 6 +++---
 1 file changed, 3 insertions(+), 3 deletions(-)

diff --git a/src/plasmaquick/plasmoid/containmentitem.cpp b/src/plasmaquick/plasmoid/containmentitem.cpp
index d8f65fc21..8d0851e9e 100644
--- a/src/plasmaquick/plasmoid/containmentitem.cpp
+++ b/src/plasmaquick/plasmoid/containmentitem.cpp
@@ -941,13 +941,13 @@ void ContainmentItem::keyPressEvent(QKeyEvent *event)
     }

     if (event->key() == Qt::Key_Menu) {
-        QPointF localPos;
+        QPointF localPos(width() / 2, height() / 2);
         auto focusedItem = window()->activeFocusItem();
         if (focusedItem) {
-            localPos = focusedItem->mapToItem(this, QPointF(0, 0));
+            localPos = focusedItem->mapToItem(this, QPointF(focusedItem->width() / 2, focusedItem->height() / 2));
         }

-        QMouseEvent me(QEvent::MouseButtonRelease, localPos, QPointF(), Qt::RightButton, Qt::RightButton, event->modifiers());
+        QMouseEvent me(QEvent::MouseButtonRelease, localPos, mapToGlobal(localPos), Qt::RightButton, Qt::RightButton, event->modifiers());
         mousePressEvent(&me);
         event->accept();
     }
